#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: probe Docker on a real remote msb sandbox, Free-plan edition.
# The first probe (probe-remote-docker.sh) hit "the Free plan runs ephemeral
# sandboxes only". `msb create` has no ephemeral flag; an UNNAMED `msb run` is
# ephemeral (removed when its command finishes), so each test is one
# `msb run` with the whole guest script. Stays within the Free plan caps
# (1 vCPU, 1 GiB RAM, 1 running at a time) and posts the output to the map
# ticket "Where does Docker's data live in a remote Runner?" (#10).
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=6

ISSUE_REPO="arteven/gh-runners-msb"
ISSUE_NUM=10
RESULTS="${RESULTS:-/tmp/msb-remote-docker-probe-ephemeral.md}"
LAST_OUT=$(mktemp)
RUN_FLAGS=(--no-tty --no-stdin --cpus 1 --memory 1G --root-disk 5G)  # cloud: 1-8 whole GiB per vCPU
RESULT_A="not run"; RESULT_B="not run"; DRIVER_A=""; DRIVER_B=""

# record "Heading" cmd...: run cmd, show + append its output to RESULTS as a
# fenced block, never abort the wizard on failure. Exit code lands in LAST_RC.
record() {
  local title="$1"; shift
  printf '\n### %s\n\n```\n' "$title" >> "$RESULTS"
  : > "$LAST_OUT"
  set +e
  "$@" 2>&1 | tee -a "$RESULTS" "$LAST_OUT"
  LAST_RC=${PIPESTATUS[0]}
  set -e
  printf '```\n' >> "$RESULTS"
}

# probe IMAGE SCRIPT: one ephemeral sandbox that runs SCRIPT with sh and is
# removed when it finishes.
probe() { msb run "${RUN_FLAGS[@]}" --entrypoint /bin/sh "$1" -- -c "$2"; }

on_exit() {
  rm -f "$LAST_OUT"
  printf '\n  %sIf a run was interrupted, check nothing lingers: msb ls%s\n' "$DIM" "$RESET"
}
trap on_exit EXIT

result_of() { grep -o "STRATEGY_$1=[A-Z]*" "$LAST_OUT" | tail -1 | cut -d= -f2 || true; }
driver_of() { grep -o '^DRIVER: .*' "$LAST_OUT" | head -1 || true; }

# ── Guest scripts ─────────────────────────────────────────────────────────
read -r -d '' GUEST_LAYOUT <<'EOF' || true
echo "=== layout"
uname -r
echo "--- root mountinfo line"; awk '$5=="/"' /proc/self/mountinfo | tail -1
echo "--- root disk (5G requested)"; df -hT /
echo "--- memory (1G requested)"; free -m
echo "--- loop devices"; ls /dev/loop* 2>&1 | head -5; losetup -f 2>&1
grep CapEff /proc/self/status
grep -E "overlay|fuse" /proc/filesystems
command -v mkfs.ext4 >/dev/null && echo "mkfs.ext4 present" || echo "mkfs.ext4 MISSING"
EOF

read -r -d '' GUEST_A <<'EOF' || true
echo "=== strategy A: Docker on the root as-is"
fail=0
dockerd >/tmp/dockerd.log 2>&1 &
if ! timeout 90 sh -c 'until docker info >/dev/null 2>&1; do sleep 1; done'; then
  tail -40 /tmp/dockerd.log; echo "STRATEGY_A=FAIL (dockerd did not start)"; exit 1
fi
echo "DRIVER: $(docker info --format '{{.Driver}} cgroup={{.CgroupVersion}}')"
docker run --rm hello-world | head -2 || fail=1
printf 'FROM alpine\nRUN echo built > /x\n' | docker build -q - || fail=1
grep -iE 'upperdir|vfs|fallback|error' /tmp/dockerd.log | tail -5
if [ "$fail" = 0 ]; then echo "STRATEGY_A=PASS"; else tail -20 /tmp/dockerd.log; echo "STRATEGY_A=FAIL"; fi
EOF

read -r -d '' GUEST_B <<'EOF' || true
echo "=== strategy B: 2G loop-mounted ext4 at /var/lib/docker"
command -v mkfs.ext4 >/dev/null || apk add -q e2fsprogs
mkdir -p /var/lib/docker
start=$(date +%s)
if ! { truncate -s 2G /docker.img && mkfs.ext4 -q /docker.img && mount -o loop /docker.img /var/lib/docker; }; then
  echo "STRATEGY_B=FAIL (loop mount)"; exit 1
fi
echo "LOOP OK (truncate+mkfs+mount took $(( $(date +%s) - start ))s)"
fail=0
dockerd >/tmp/dockerd.log 2>&1 &
if ! timeout 90 sh -c 'until docker info >/dev/null 2>&1; do sleep 1; done'; then
  tail -40 /tmp/dockerd.log; echo "STRATEGY_B=FAIL (dockerd did not start)"; exit 1
fi
echo "DRIVER: $(docker info --format '{{.Driver}}')"
docker run --rm hello-world | head -2 || fail=1
printf 'FROM alpine\nRUN echo built > /x\n' | docker build -q - || fail=1
docker run -d --name svc -p 8080:80 nginx:alpine >/dev/null && sleep 3 \
  && wget -qO- localhost:8080 | head -1 || fail=1
df -h / /var/lib/docker; free -m
if [ "$fail" = 0 ]; then echo "STRATEGY_B=PASS"; else tail -20 /tmp/dockerd.log; echo "STRATEGY_B=FAIL"; fi
EOF

read -r -d '' GUEST_RUNNER <<'EOF' || true
awk '$5=="/"' /proc/self/mountinfo | tail -1
df -hT /
du -sh /home/runner 2>/dev/null
EOF

banner "Probe Docker on remote msb (Free plan, ephemeral)"
printf '# Remote Docker probe results (ephemeral)\n\nRun %s\n' "$(date -u +%Y-%m-%dT%H:%MZ)" > "$RESULTS"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Check tools and select the remote profile"
say "Runs three short-lived EPHEMERAL sandboxes, one after another, on your cloud"
say "account, within the Free plan limits: 1 GiB RAM, so 1 vCPU (cloud needs"
say "1-8 GiB per vCPU). Each one is an unnamed 'msb run', removed as soon as its"
say "script finishes. About 10 minutes."
note "Output is saved to $RESULTS"
printf '\n'
command -v msb >/dev/null 2>&1 || { warn "msb not found on PATH. Install it and re-run."; exit 1; }
command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1 \
  || warn "gh is not logged in: you'll paste the output into the issue by hand at the end."
ask MSB_CONTEXT "Name of your remote msb profile (Enter for 'remote'):" || true
MSB_CONTEXT="${MSB_CONTEXT:-remote}"
step "Switching profile (this changes your active msb context):"
msb context use "$MSB_CONTEXT"
confirm "Is '$MSB_CONTEXT' the cloud (remote) profile, not the local one?" \
  || { warn "Fix the profile (msb context use <name>) and re-run."; exit 1; }

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Check run flags and leftovers"
RUN_HELP=$(msb run --help 2>&1 || true)
if grep -q -- '--max-duration' <<<"$RUN_HELP"; then
  RUN_FLAGS+=(--max-duration 20m); say "msb run supports --max-duration: capping each run at 20m."
else
  note "msb run has no --max-duration; the Free plan's 60-minute cap still applies."
fi
for flag in --no-tty --no-stdin --entrypoint --root-disk; do
  grep -q -- "$flag" <<<"$RUN_HELP" || warn "msb run --help doesn't list $flag; the runs may fail."
done
printf 'msb run flags: `%s`\n' "${RUN_FLAGS[*]}" >> "$RESULTS"
record "Existing sandboxes (Free plan: 3 total, 1 running)" msb ls
say "If anything is RUNNING above, stop it first (msb stop <name>): only one may run."
pause "Enter to start the first probe"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Probe 1: layout, then Docker on the root as-is (strategy A)"
say "msb run docker:dind (1 CPU, 1G RAM, 5G root): layout, then hello-world + a build."
record "Probe 1: layout + strategy A" probe docker:dind "$GUEST_LAYOUT
$GUEST_A"
(( LAST_RC == 0 )) || warn "msb run exited $LAST_RC (the output above says why)."
RESULT_A=$(result_of A); RESULT_A="${RESULT_A:-no result}"; DRIVER_A=$(driver_of)
say "Strategy A: $RESULT_A  $DRIVER_A"
pause "Enter to continue"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Probe 2: loop-mounted ext4 at /var/lib/docker (strategy B)"
say "A fresh msb run docker:dind: 2G sparse ext4 file (the --docker-disk default),"
say "loop-mounted at /var/lib/docker; hello-world, a build and an nginx service."
record "Probe 2: strategy B (loop ext4, 2G)" probe docker:dind "$GUEST_B"
(( LAST_RC == 0 )) || warn "msb run exited $LAST_RC (the output above says why)."
RESULT_B=$(result_of B); RESULT_B="${RESULT_B:-no result}"; DRIVER_B=$(driver_of)
say "Strategy B: $RESULT_B  $DRIVER_B"
pause "Enter to continue"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Probe 3: root-disk footprint of the real Runner base image"
say "The Runner image is based on ghcr.io/actions/actions-runner (~1.5 GB unpacked)."
say "This shows how much of a 5G remote root disk it leaves free (a big pull)."
record "Probe 3: actions-runner root footprint" probe ghcr.io/actions/actions-runner:latest "$GUEST_RUNNER"
(( LAST_RC == 0 )) || warn "msb run exited $LAST_RC (the output above says why)."
pause "Enter to continue"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Post the output to issue #$ISSUE_NUM"
BODY=$(mktemp)
{
  printf '## Remote Docker probe results (ephemeral, Free plan)\n\n'
  printf -- '- Strategy A (Docker on root as-is): **%s** %s\n' "$RESULT_A" "$DRIVER_A"
  printf -- '- Strategy B (loop-mounted ext4, 2G): **%s** %s\n\n' "$RESULT_B" "$DRIVER_B"
  sed '1d' "$RESULTS"
} > "$BODY"
say "Full output is in: $BODY"
warn "Skim it first: the sandbox listing may show names you don't want public."
if confirm "Post it as a comment on issue #$ISSUE_NUM in $ISSUE_REPO?"; then
  if gh issue comment "$ISSUE_NUM" --repo "$ISSUE_REPO" --body-file "$BODY" >/dev/null; then
    say "Posted. Tell the agent the probe results are on #$ISSUE_NUM."
  else
    SKIPPED+=("post $BODY to issue #$ISSUE_NUM by hand")
  fi
else
  SKIPPED+=("post $BODY to issue #$ISSUE_NUM by hand")
fi

finish
}

run_wizard "$@"; exit
